<?php

declare(strict_types=1);

namespace App\Repository;

use App\Entity\Invitation;
use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository;
use Doctrine\DBAL\LockMode;
use Doctrine\Persistence\ManagerRegistry;

/**
 * @extends ServiceEntityRepository<Invitation>
 * This class was generated by the Doctrine ORM. Add your own custom
 */
final class InvitationRepository extends ServiceEntityRepository implements InvitationRepositoryInterface
{
    /**
     * @param ManagerRegistry $registry
     *
     */
    public function __construct(ManagerRegistry $registry)
    {
        parent::__construct($registry, Invitation::class);
    }

    /**
     * @param int $gameId
     *
     * @return Invitation|null
     */
    #[\Override]
    public function findOneByGameIdForShare(int $gameId): ?Invitation
    {
        /** @var Invitation|null $invitation */
        $invitation = $this->createQueryBuilder('i')
            ->andWhere('IDENTITY(i.game) = :gameId')
            ->setParameter('gameId', $gameId)
            ->getQuery()
            ->setLockMode(LockMode::PESSIMISTIC_READ)
            ->getOneOrNullResult();

        return $invitation;
    }
}
